// Package gensource identifies the Go files tinybind itself wrote.
package gensource

import (
	"go/ast"
	"strings"
)

// headerPrefix is what every generated file of this tool leads with. The suffix
// varies by artifact ("by tinybind", "by tinybind templates"), so the prefix is
// what identifies the writer.
const headerPrefix = "Code generated by tinybind"

const headerSuffix = "DO NOT EDIT."

// IsGenerated reports whether file was written by tinybind.
//
// Discovery skips such a file. A generated registry registers the pages of a
// route tree, so reading it back would discover those pages as routes and put an
// HTML page and its action endpoints into an OpenAPI document, which is exactly
// what a page route is not. The same applies to a generated binder or component:
// nothing this tool wrote is an input to what it reads.
//
// Another tool's generated code is deliberately not skipped. Its registrations
// are a user's own API surface, and dropping them would remove routes from a
// document with nothing said about it.
func IsGenerated(file *ast.File) bool {
	if file == nil {
		return false
	}
	for _, group := range file.Comments {
		// Only the header can precede the package clause, so nothing further in
		// the file can claim the file was generated.
		if file.Package != 0 && group.Pos() > file.Package {
			break
		}
		for _, comment := range group.List {
			text := strings.TrimSpace(strings.TrimPrefix(strings.TrimPrefix(comment.Text, "//"), "/*"))
			if strings.HasPrefix(text, headerPrefix) && strings.HasSuffix(text, headerSuffix) {
				return true
			}
		}
	}
	return false
}
